-- S3: at the cap: 288 slots with 7 rows each, 2,016 in the read range. 2016 rows in the table, 2016 in the read range.
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 287) INSERT INTO collector_runs (layer, started_at, finished_at, status, http_status, records, bytes, note) SELECT 'earthview', strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600, 'unixepoch'), strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600 + 15, 'unixepoch'), 'ok', 200, 0, 0, 'nothing newer: fixture frame' FROM n;
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 287), r(j) AS (SELECT 1 UNION ALL SELECT j + 1 FROM r WHERE j < 6) INSERT INTO collector_runs (layer, started_at, finished_at, status, http_status, records, bytes, note) SELECT 'earthview', strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600, 'unixepoch'), strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600 + 15 + j, 'unixepoch'), 'ok', 200, 0, 0, 'nothing newer: fixture repeat' FROM n, r;
